// Check if Already Run Today (Idempotency)
const today = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
const workflowData = $getWorkflowStaticData('global');
const lastRun = workflowData.lastSuccessfulRun;

if (lastRun === today) {
  console.log(`ETL already completed for ${today}. Skipping.`);
  return []; // Stop execution
}

console.log(`Starting ETL for ${today}`);
return [{ json: { runDate: today } }];

// Acquire Distributed Lock
const lockKey = `etl_salesforce_postgresql_lock`;
const locks = $getWorkflowStaticData('global').locks || {};
const now = Date.now();
const LOCK_TIMEOUT = 3600000; // 1 hour

// Check if lock exists and not expired
if (locks[lockKey] && (now - locks[lockKey].acquired < LOCK_TIMEOUT)) {
  const lockAge = Math.round((now - locks[lockKey].acquired) / 1000);
  throw new Error(`ETL already running (started ${lockAge}s ago). Aborting.`);
}

// Acquire lock
locks[lockKey] = {
  acquired: now,
  executionId: $execution.id,
  startedAt: new Date().toISOString()
};

$setWorkflowStaticData('global', { locks });

console.log(`Lock acquired for execution ${$execution.id}`);
return $input.all();

// Extract Records from Salesforce Response
const response = $json;
const records = response.records || [];

console.log(`Fetched ${records.length} contacts from Salesforce`);

if (records.length === 0) {
  console.log('No records to process. Exiting.');
  return [];
}

return records.map(record => ({ json: record }));

// Validate Input Schema
const Joi = require('joi');

const contactSchema = Joi.object({
  Id: Joi.string().required(),
  Name: Joi.string().min(1).max(255).required(),
  Email: Joi.string().email().allow(null, '').optional(),
  Phone: Joi.string().allow(null, '').optional(),
  CreatedDate: Joi.date().iso().required(),
  LastModifiedDate: Joi.date().iso().required()
});

const items = $input.all();
const validated = [];
const errors = [];

for (const [index, item] of items.entries()) {
  const { error, value } = contactSchema.validate(item.json, {
    abortEarly: false,
    stripUnknown: true
  });

  if (error) {
    errors.push({
      index,
      salesforceId: item.json.Id,
      errors: error.details.map(d => d.message)
    });
  } else {
    validated.push(value);
  }
}

if (errors.length > 0) {
  console.warn(`Validation errors: ${JSON.stringify(errors)}`);
  // Continue with valid records
}

console.log(`Validated ${validated.length}/${items.length} records`);

return validated.map(item => ({ json: item }));

// Transform Salesforce to PostgreSQL Format
const items = $input.all();

const transformed = items.map(item => {
  const sf = item.json;

  return {
    salesforce_id: sf.Id,
    name: sf.Name,
    email: sf.Email || null,
    phone: sf.Phone || null,
    created_at: new Date(sf.CreatedDate).toISOString(),
    last_modified_at: new Date(sf.LastModifiedDate).toISOString(),
    synced_at: new Date().toISOString()
  };
});

console.log(`Transformed ${transformed.length} records`);

return transformed.map(item => ({ json: item }));

// Validate Output Schema
const Joi = require('joi');

const outputSchema = Joi.object({
  salesforce_id: Joi.string().required(),
  name: Joi.string().min(1).max(255).required(),
  email: Joi.string().email().allow(null).optional(),
  phone: Joi.string().allow(null).optional(),
  created_at: Joi.date().iso().required(),
  last_modified_at: Joi.date().iso().required(),
  synced_at: Joi.date().iso().required()
});

const items = $input.all();
const validated = [];
const errors = [];

for (const [index, item] of items.entries()) {
  const { error, value } = outputSchema.validate(item.json, {
    abortEarly: false,
    stripUnknown: true
  });

  if (error) {
    errors.push({
      index,
      salesforceId: item.json.salesforce_id,
      errors: error.details.map(d => d.message)
    });
  } else {
    validated.push(value);
  }
}

if (errors.length > 0) {
  throw new Error(`Output validation failed: ${JSON.stringify(errors)}`);
}

return validated.map(item => ({ json: item }));

// Log Batch Progress
const batchIndex = $node["Split In Batches"].context.noItemsLeft ? 'final' : $node["Split In Batches"].context.currentRunIndex;
const itemCount = $input.all().length;

console.log(`Batch ${batchIndex} processed: ${itemCount} records inserted/updated`);

return $input.all();

// Release Lock + Mark Success
const lockKey = `etl_salesforce_postgresql_lock`;
const locks = $getWorkflowStaticData('global').locks || {};

// Release lock
delete locks[lockKey];

// Mark successful run
const today = new Date().toISOString().split('T')[0];
const stats = $getWorkflowStaticData('global').stats || {};

stats.lastSuccessfulRun = today;
stats.lastExecutionId = $execution.id;
stats.lastRunTimestamp = Date.now();

$setWorkflowStaticData('global', { 
  locks, 
  stats,
  lastSuccessfulRun: today 
});

console.log(`Lock released. ETL completed successfully for ${today}`);

return [{ 
  json: { 
    status: 'success',
    runDate: today,
    executionId: $execution.id
  } 
}];

// Calculate Statistics
const workflowData = $getWorkflowStaticData('global');
const stats = workflowData.stats || {};

// Get total records processed (approximation based on batches)
const batchSize = 100;
const totalBatches = $node["Split In Batches"].context.currentRunIndex || 0;
const totalRecords = totalBatches * batchSize;

const executionTime = Date.now() - new Date($execution.startedAt).getTime();

const summary = {
  date: new Date().toISOString().split('T')[0],
  totalRecords: totalRecords,
  executionTime: `${Math.round(executionTime / 1000)}s`,
  status: 'success',
  executionId: $execution.id
};

console.log(`ETL Summary: ${JSON.stringify(summary)}`);

return [{ json: summary }];

